<?php
require_once '../includes/auth.php'; require_once '../config/koneksi.php';
$q=trim($_GET['q']??''); $like="%$q%";
$st=$conn->prepare("SELECT k.*, (SELECT COUNT(*) FROM siswa s WHERE s.kelas COLLATE utf8mb4_unicode_ci = k.nama_kelas COLLATE utf8mb4_unicode_ci) jumlah_siswa FROM kelas k WHERE k.nama_kelas LIKE ? OR k.tingkat LIKE ? OR COALESCE(k.wali_kelas,'') LIKE ? ORDER BY FIELD(k.tingkat,'VII','VIII','IX'),k.nama_kelas");
$st->bind_param('sss',$like,$like,$like);$st->execute();$rows=$st->get_result();
$page_title='Data Kelas';$active='kelas';$prefix='../';include '../includes/header.php'; ?>
<div class="page-heading"><div><h1>Data Kelas SMP</h1><p>Kelola tingkat VII, VIII, IX, rombongan belajar, dan wali kelas.</p></div><a class="btn btn-primary" href="tambah.php"><i class="bi bi-plus-lg me-1"></i>Tambah Kelas</a></div>
<div class="row g-3 mb-3"><?php foreach(['VII'=>'Kelas VII','VIII'=>'Kelas VIII','IX'=>'Kelas IX'] as $t=>$label): $c=$conn->prepare("SELECT COUNT(*) n FROM kelas WHERE tingkat=? AND status='aktif'");$c->bind_param('s',$t);$c->execute();$n=$c->get_result()->fetch_assoc()['n']; ?><div class="col-md-4"><div class="stat-card"><div class="stat-label"><?= e($label) ?></div><div class="stat-value"><?= (int)$n ?> <span class="fs-6 fw-normal text-secondary">kelas aktif</span></div></div></div><?php endforeach;?></div>
<?php if(isset($_GET['success'])): ?><div class="alert alert-success py-2"><?= $_GET['success']==='tambah'?'Kelas berhasil ditambahkan.':($_GET['success']==='edit'?'Perubahan kelas berhasil disimpan.':'') ?></div><?php endif; ?>
<div class="panel"><div class="panel-head"><div><strong>Daftar Kelas</strong><div class="text-secondary small">Jumlah siswa dihitung dari data siswa yang terdaftar.</div></div><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Cari kelas / wali kelas"><button class="btn btn-outline-primary"><i class="bi bi-search"></i></button></form></div><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Tingkat</th><th>Nama Kelas</th><th>Wali Kelas</th><th>Jumlah Siswa</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $i=0;while($r=$rows->fetch_assoc()):?><tr><td><?= ++$i ?></td><td><span class="badge-soft"><?= e($r['tingkat']) ?></span></td><td><strong><?= e($r['nama_kelas']) ?></strong></td><td><?= e($r['wali_kelas']?:'-') ?></td><td><?= (int)$r['jumlah_siswa'] ?></td><td><span class="badge <?= $r['status']==='aktif'?'text-bg-success':'text-bg-secondary' ?>"><?= e(ucfirst($r['status'])) ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= (int)$r['id_kelas'] ?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" data-confirm="Hapus kelas ini? Kelas yang dipakai siswa tidak dapat dihapus." href="hapus.php?id=<?= (int)$r['id_kelas'] ?>"><i class="bi bi-trash"></i></a></td></tr><?php endwhile;if($i===0):?><tr><td colspan="7" class="empty">Belum ada kelas.</td></tr><?php endif;?></tbody></table></div></div><?php include '../includes/footer.php'; ?>